<?php
declare(strict_types=1);
require_once __DIR__ . "/../../includes/seguridad.php";
exigirAdmin();
function e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$id=(int)($_GET['id']??$_POST['id_unidad']??0);$errores=[];$mensajes=[];
if(empty($_SESSION['csrf_unidad_edit']))$_SESSION['csrf_unidad_edit']=bin2hex(random_bytes(32));$csrf=$_SESSION['csrf_unidad_edit'];
try{$st=$conexion->prepare("SELECT u.*,m.nombre AS materia,COUNT(t.id_tema) AS total_temas FROM unidades_tematicas u INNER JOIN materias m ON m.id_materia=u.id_materia LEFT JOIN temas t ON t.id_unidad=u.id_unidad WHERE u.id_unidad=? GROUP BY u.id_unidad,m.nombre");$st->execute([$id]);$unidad=$st->fetch(PDO::FETCH_ASSOC);if(!$unidad)$errores[]='La unidad temática no existe.';}catch(PDOException $ex){$unidad=null;$errores[]='No fue posible cargar la unidad temática.';}
if($_SERVER['REQUEST_METHOD']==='POST' && $unidad){
 if(!hash_equals($csrf,(string)($_POST['csrf']??'')))$errores[]='La sesión del formulario expiró. Recarga la página.';
 else{
  $nombre=trim((string)($_POST['nombre']??''));$descripcion=trim((string)($_POST['descripcion']??''));
  if($nombre==='')$errores[]='El nombre es obligatorio.';elseif(mb_strlen($nombre)>100)$errores[]='El nombre no puede superar los 100 caracteres.';
  if(mb_strlen($descripcion)>500)$errores[]='La descripción no puede superar los 500 caracteres.';
  if(!$errores)try{
   $st=$conexion->prepare("SELECT COUNT(*) FROM unidades_tematicas WHERE id_materia=? AND grado=? AND LOWER(nombre)=LOWER(?) AND id_unidad<>?");$st->execute([$unidad['id_materia'],$unidad['grado'],$nombre,$id]);
   if((int)$st->fetchColumn()>0)$errores[]='Ya existe otra unidad con ese nombre en esa materia y grado.';
   else{$st=$conexion->prepare("UPDATE unidades_tematicas SET nombre=?,descripcion=? WHERE id_unidad=?");$st->execute([$nombre,$descripcion!==''?$descripcion:null,$id]);$mensajes[]='Unidad temática actualizada correctamente.';$unidad['nombre']=$nombre;$unidad['descripcion']=$descripcion;}
  }catch(PDOException $ex){$errores[]='No fue posible actualizar la unidad temática.';}
 }
}
$urlDashboard=urlAplicacion('/admin/dashboard.php');$urlUnidades=urlAplicacion('/admin/contenidos/unidades.php');$urlSalir=urlAplicacion('/cerrar_sesion.php');$urlTemas=urlAplicacion('/admin/contenidos/temas.php?id_unidad='.$id);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar unidad temática | Studia360</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="<?=e(urlAplicacion('/admin/assets/studia-admin.css'))?>"><style>body{background:#f6f8fc}.form-card{max-width:760px;margin:auto;background:#fff;border:1px solid #e5eaf1;border-radius:22px;padding:26px;box-shadow:0 12px 32px rgba(23,32,51,.06)}.s360-shell{width:min(900px,calc(100% - 30px));margin:auto;padding:28px 0 60px}.s360-hero{border-radius:22px;padding:24px;background:linear-gradient(125deg,#2563eb,#4f46e5);color:#fff}.s360-hero h1{color:#fff}.meta{font-size:.8rem;color:#748196}.form-control{border-radius:11px}</style></head><body class="s360-admin s360-content-theme"><nav class="s360-topbar"><div class="container-fluid px-3 px-lg-4 py-2 d-flex justify-content-between align-items-center"><a class="s360-brand d-flex align-items-center gap-2" href="<?=e($urlDashboard)?>"><span class="s360-brand-icon"><i class="bi bi-mortarboard-fill"></i></span>Studia360 <span class="badge text-bg-primary">Admin</span></a><div class="d-flex gap-2"><a class="btn btn-light border" href="<?=e($urlUnidades)?>"><i class="bi bi-arrow-left me-1"></i>Unidades</a><a class="btn btn-outline-secondary" href="<?=e($urlSalir)?>">Salir</a></div></div></nav><main class="s360-shell"><?php if($unidad):?><section class="s360-hero mb-4"><div class="small fw-bold opacity-75 text-uppercase">Editar unidad temática</div><h1 class="h2 mb-2"><?=e($unidad['nombre'])?></h1><p class="mb-0 opacity-75"><?=e($unidad['materia'])?> · <?=e($unidad['grado'])?>° · <?=((int)$unidad['total_temas'])?> tema(s)</p></section><?php endif;?><?php foreach($errores as $er):?><div class="alert alert-danger border-0 shadow-sm"><?=e($er)?></div><?php endforeach;?><?php foreach($mensajes as $m):?><div class="alert alert-success border-0 shadow-sm"><?=e($m)?></div><?php endforeach;?><?php if($unidad):?><section class="form-card"><div class="d-flex justify-content-between align-items-start gap-3 mb-4"><div><h2 class="h5 fw-bold mb-1">Información</h2><p class="meta mb-0">Materia y grado: <strong><?=e($unidad['materia'])?> · <?=e($unidad['grado'])?>°</strong></p></div><?php if((int)$unidad['total_temas']>0):?><a class="btn btn-outline-primary btn-sm" href="<?=e($urlTemas)?>"><i class="bi bi-journal-text me-1"></i>Ver temas</a><?php endif;?></div><?php if((int)$unidad['es_predeterminada']===1):?><div class="alert alert-info border-0"><i class="bi bi-info-circle me-1"></i>Esta es una <strong>Temática general</strong> creada durante la migración. Su materia y grado se mantienen fijos y funciona como unidad de transición.</div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="id_unidad" value="<?=$id?>"><label class="form-label fw-semibold">Nombre</label><input class="form-control mb-3" name="nombre" maxlength="100" required value="<?=e($unidad['nombre'])?>"><label class="form-label fw-semibold">Descripción <span class="text-secondary fw-normal">(opcional)</span></label><textarea class="form-control" name="descripcion" maxlength="500" rows="4"><?=e($unidad['descripcion']??'')?></textarea><div class="d-flex justify-content-end gap-2 mt-4"><a class="btn btn-light border" href="<?=e($urlUnidades)?>">Cancelar</a><button class="btn btn-primary" type="submit"><i class="bi bi-check2 me-1"></i>Guardar cambios</button></div></form></section><?php endif;?></main></body></html>
